const src = $json;
const handoff = $('When Executed by Parse v11').first().json || {};
const required = ['contract_version','qualification_test_id','run_id','document_id','source_sha256','source_file_name','source_mime_type','source_extension','source_text','carrier','product_line','validated_review'];
for (const key of required) if (handoff[key] === undefined || handoff[key] === null || handoff[key] === '') throw new Error('HANDOFF_INVALID: missing '+key);
if (handoff.contract_version !== 'kkb.stage5.parse-index.v1') throw new Error('HANDOFF_INVALID: unsupported contract');
if (src.document_version_id !== handoff.document_id || src.sha256 !== handoff.source_sha256) throw new Error('HANDOFF_INVALID: approved version does not match handoff identity');
return {json:{...src, ...handoff, allow_supersede_replace:false, superseded_version_ids:Array.isArray(src.superseded_version_ids)?src.superseded_version_ids:[], vertex_project_id_confirmed:'katie-knowledge-base-n8n',vertex_embedding_model_confirmed:'text-embedding-004',vertex_embedding_output_dimension_confirmed:768}};

function sha256Hex(str) {
  function rrot(n, x) { return (x >>> n) | (x << (32 - n)); }
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;

  const bytes = Buffer.from(str, 'utf8');
  const bitLen = bytes.length * 8;
  const padLen = (((bytes.length + 8) >> 6) + 1) << 6;
  const padded = Buffer.alloc(padLen);
  bytes.copy(padded);
  padded[bytes.length] = 0x80;
  padded.writeUInt32BE(Math.floor(bitLen / 0x100000000), padLen - 8);
  padded.writeUInt32BE(bitLen >>> 0, padLen - 4);

  const w = new Array(64);
  for (let offset = 0; offset < padded.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = padded.readUInt32BE(offset + i * 4);
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rrot(7, w[i-15]) ^ rrot(18, w[i-15]) ^ (w[i-15] >>> 3);
      const s1 = rrot(17, w[i-2]) ^ rrot(19, w[i-2]) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let i = 0; i < 64; i++) {
      const S1 = rrot(6,e) ^ rrot(11,e) ^ rrot(25,e);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rrot(2,a) ^ rrot(13,a) ^ rrot(22,a);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+temp1)>>>0; d=c; c=b; b=a; a=(temp1+temp2)>>>0;
    }
    h0=(h0+a)>>>0; h1=(h1+b)>>>0; h2=(h2+c)>>>0; h3=(h3+d)>>>0;
    h4=(h4+e)>>>0; h5=(h5+f)>>>0; h6=(h6+g)>>>0; h7=(h7+h)>>>0;
  }
  return [h0,h1,h2,h3,h4,h5,h6,h7].map(x => x.toString(16).padStart(8, '0')).join('');
}
const CHUNK_SIZE = 800;
const OVERLAP = 100;
const inputItems = $input.all();
const approvedItems = $('Validate Index Preconditions').all();
const out = [];

function toUuid(md5Hex) {
  return md5Hex.slice(0, 8) + '-' + md5Hex.slice(8, 12) + '-' + md5Hex.slice(12, 16) + '-' + md5Hex.slice(16, 20) + '-' + md5Hex.slice(20, 32);
}

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const src = approvedItems[i] && approvedItems[i].json ? approvedItems[i].json : null;
  if (!src) {
    throw new Error('CHUNK_FAILED: missing approved source metadata for item ' + i);
  }

  const keys = Object.keys(item.binary || {});
  if (keys.length === 0) {
    throw new Error('CHUNK_FAILED: no binary property found for item ' + i);
  }

  const key = keys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const sourceSha256 = sha256Hex(buffer.toString('utf8')); 
  if (src.sha256 && sourceSha256 !== src.sha256) {
    throw new Error('SUPERSEDE_CONFLICT: source hash mismatch for document_version_id ' + src.document_version_id);
  }

  const text = buffer.toString('utf8');
  if (!text.trim()) {
    throw new Error('EMPTY_TEXT: document_version_id ' + src.document_version_id);
  }

  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = Math.min(start + CHUNK_SIZE, text.length);
    const chunkText = text.slice(start, end).trim();
    if (chunkText.length > 0) {
      chunks.push({ start, end, chunkText });
    }
    if (end >= text.length) {
      break;
    }
    start = end - OVERLAP;
    if (start < 0) {
      start = 0;
    }
  }

  if (chunks.length === 0) {
    throw new Error('EMPTY_TEXT: document_version_id ' + src.document_version_id);
  }

  for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
    const chunk = chunks[chunkIndex];
    const chunkDigest = sha256Hex(src.document_version_id + ':' + chunkIndex);
    const chunkId = toUuid(chunkDigest);
    out.push({
      json: {
        document_version_id: src.document_version_id,
        file_name: src.file_name,
        raw_path: src.raw_path,
        sha256: src.sha256,
        source_sha256: sourceSha256,
        contract_version: src.contract_version,
        qualification_test_id: src.qualification_test_id,
        run_id: src.run_id,
        validated_review: src.validated_review,
        allow_supersede_replace: src.allow_supersede_replace,
        superseded_version_ids: src.superseded_version_ids,
        chunk_id: chunkId,
        chunk_index: chunkIndex,
        chunk_text: chunk.chunkText,
        token_count: Math.ceil(chunk.chunkText.length / 4),
        cite_locator: 'chars ' + chunk.start + '-' + chunk.end,
        expected_chunk_count: chunks.length,
        vertex_project_id_confirmed: src.vertex_project_id_confirmed,
        vertex_embedding_model_confirmed: src.vertex_embedding_model_confirmed,
        vertex_embedding_output_dimension_confirmed: src.vertex_embedding_output_dimension_confirmed
      }
    });
  }
}

return out;

const items = $input.all();
if (items.length === 0) {
  throw new Error('COUNT_MISMATCH: no chunk items received');
}

const groups = new Map();
for (const item of items) {
  const docId = item.json.document_version_id;
  if (!groups.has(docId)) {
    groups.set(docId, []);
  }
  groups.get(docId).push(item);
}

const out = [];
for (const [docId, groupItems] of groups.entries()) {
  const expected = Number(groupItems[0].json.expected_chunk_count || groupItems.length);
  const existingCounts = [...new Set(groupItems.map((item) => Number(item.json.existing_chunk_count || 0)))];
  if (existingCounts.length !== 1) {
    throw new Error('COUNT_MISMATCH: inconsistent existing chunk counts for document_version_id ' + docId);
  }

  const existing = existingCounts[0];
  const src = groupItems[0].json;
  if (existing === expected) {
    out.push({
      json: {
        index_status: 'already_indexed',
        ok: true,
        code: 'INDEX_COMPLETE',
        document_version_id: docId,
        chunk_count: expected,
        embedding_count: expected,
        superseded_version_ids: src.superseded_version_ids || [],
        source_sha256: src.source_sha256,
        allow_supersede_replace: src.allow_supersede_replace === true,
        dedupe_mode: 'chunk_id_conflict_prevented_duplicate_rows'
      }
    });
    continue;
  }

  if (existing > 0 && existing < expected) {
    throw new Error('COUNT_MISMATCH: partial existing chunk set for document_version_id ' + docId + ' existing=' + existing + ' expected=' + expected);
  }

  for (const item of groupItems) {
    out.push({
      json: {
        ...item.json,
        index_status: 'fresh'
      }
    });
  }
}

return out;

