}

const embedding = chunkJson.embedding_raw;
if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error('EMBED_FAILED: no embedding vector returned for document_version_id ' + documentVersionId + ' chunk_index ' + chunkIndex);
}

const expectedDimensionsRaw = chunkJson.vertex_embedding_output_dimension_confirmed;
const expectedDimensions = Number(expectedDimensionsRaw);
if (Number.isFinite(expectedDimensions) && expectedDimensions > 0 && embedding.length !== expectedDimensions) {
  throw new Error('DIMENSION_MISMATCH: expected ' + expectedDimensions + ' actual ' + embedding.length + ' for document_version_id ' + documentVersionId + ' chunk_index ' + chunkIndex);
}

return {
  json: {
    ...chunkJson,
    ok: true,
    fault_code: null,
    embedding_vector: JSON.stringify(embedding),
    embedding_dimensions_actual: embedding.length,
    embedding_dimensions_expected: expectedDimensionsRaw,
    embedding_model: chunkJson.vertex_embedding_model_confirmed
  }
};

const chunk = $('Chunk Text').item.json;
const existing = Number($json.existing_chunk_count);
if (!Number.isInteger(existing) || existing < 0) throw new Error('COUNT_MISMATCH: invalid existing chunk count');
return { json: { ...chunk, existing_chunk_count: existing } };

