"use strict";
function stripFence(s) {
  const t = String(s).trim();
  const m = t.match(/^```[a-zA-Z]*\s*\n?([\s\S]*?)\n?```$/);
  return m ? m[1].trim() : t;
}
const retrieval = $('Aggregate Retrieval').first().json;
const raw = $json.text !== undefined ? $json.text : '';
let parsed = null;
try { parsed = JSON.parse(stripFence(raw)); } catch (e) { parsed = null; }
if (!parsed || typeof parsed.answer !== 'string') {
  return { json: { answer: "I don't have enough support in the indexed documents to answer that.", citations: [], top_similarity: retrieval.top_similarity, similarity_threshold: retrieval.similarity_threshold, model_parse_fault: true } };
}
const groundedIds = Array.isArray(parsed.grounded_chunk_ids) ? parsed.grounded_chunk_ids.filter((id) => typeof id === 'string' && id.length > 0) : [];
const groundedSet = new Set(groundedIds);
const citations = retrieval.retrieved.filter((r) => groundedSet.has(r.chunk_id)).map((r) => ({ chunk_id: r.chunk_id, document_version_id: r.document_version_id, cite_locator: r.cite_locator }));
return { json: { answer: parsed.answer, citations, top_similarity: retrieval.top_similarity, similarity_threshold: retrieval.similarity_threshold, model_reported_supported: parsed.supported === true } };

