// Output handler: strip a markdown fence if present, then parse the WHOLE remaining
// string. Deliberately strict - no substring extraction, so arrays and surrounding
// prose cannot slip through.
function stripFence(s) {
  const t = String(s).trim();
  const m = t.match(/^```[a-zA-Z]*\s*\n?([\s\S]*?)\n?```$/);
  return m ? m[1].trim() : t;
}
