  catch (e) { errors.push('JSON.parse of full response failed: ' + e.message); }
}

if (parse_ok) {
  if (candidate === null) { errors.push('parsed value is null'); }
  else if (Array.isArray(candidate)) { errors.push('parsed value is an array, expected object'); }
