function assessContent(signals) {
  try {
    const input = signals && typeof signals === 'object' ? signals : {};

    const extractedTextLength =
      input.extractedTextLength === undefined ? 0 : input.extractedTextLength;
    const pageCount = input.pageCount === undefined ? null : input.pageCount;
    const isEncrypted = input.isEncrypted === true;
    const hasMacros = input.hasMacros === true;
    const hasActiveScript = input.hasActiveScript === true;
    const decodeFault = input.decodeFault === 'PARSE_FAILED';
    const rawText = typeof input.rawText === 'string' ? input.rawText : '';
