'use strict';

const DETECTORS = [
  {
    type: 'ssn',
    pattern: /\b(?!000|666|9\d{2})\d{3}(?:-\d{2}-\d{4}| \d{2} \d{4}|\d{6})\b/,
  },
  {
    type: 'phone',
    pattern: /(?:^|[^\dA-Z])(?:\+1[\s.-]?)?(?:\(\d{3}\)\s*|\d{3}[\s.-])\d{3}[\s.-]\d{4}\b/i,
  },
  {
    type: 'email',
    pattern: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i,
  },
  {
    type: 'address',
    pattern: /\b\d{1,6}\s+(?:[A-Z0-9'.-]+\s+){1,6}(?:St|Street|Ave|Avenue|Rd|Road|Blvd|Dr|Drive|Ln|Lane|Way|Ct|Court)\.?\b/i,
  },
  {
    type: 'policy_or_member_id',
    pattern: /\b(?:policy|member)\s+(?:(?:no|number|id)\.?\s*:?\s*|#\s*)[A-Z0-9][A-Z0-9-]{2,}\b/i,
  },
  {
    type: 'person_name_hint',
    pattern: /\b(?:Named\s+Insured|Insured|Dear|Attn|Applicant)\s*:?\s+[A-Z][A-Za-z'.-]+\s+[A-Z][A-Za-z'.-]+\b/,
  },
];

function detectPII(text) {
  if (typeof text !== 'string' || text.length === 0) {
    return { pii_types: [] };
  }

  const pii_types = [];
  for (const detector of DETECTORS) {
    if (detector.pattern.test(text)) {
      pii_types.push(detector.type);
    }
  }

  return { pii_types };
}

