"use strict";

function assessContent(signals) {
  try {
    const input = signals && typeof signals === 'object' ? signals : {};

    const extractedTextLength =
      input.extractedTextLength === undefined ? 0 : input.extractedTextLength;
    const pageCount = input.pageCount === undefined ? null : input.pageCount;
    const isEncrypted = input.isEncrypted === true;
    const hasMacros = input.hasMacros === true;
    const hasActiveScript = input.hasActiveScript === true;
    const decodeFault = input.decodeFault === 'PARSE_FAILED';
    const rawText = typeof input.rawText === 'string' ? input.rawText : '';
    const trimmedLength = rawText.trim().length;
    const replacementCharCount = (rawText.match(/�/g) || []).length;
    const controlCharCount = (rawText.match(/[�-  -]/g) || []).length;

    if (isEncrypted || decodeFault) {
      return { ok: false, code: 'PARSE_FAILED' };
    }

    if (
      typeof extractedTextLength !== 'number' ||
      !Number.isFinite(extractedTextLength) ||
      extractedTextLength < 0
    ) {
      return { ok: false, code: 'PARSE_FAILED' };
    }

    if (hasMacros || hasActiveScript) {
      return { ok: false, code: 'ACTIVE_CONTENT' };
    }

    if (replacementCharCount > 0 || controlCharCount > Math.max(10, Math.floor(rawText.length * 0.1))) {
      return { ok: false, code: 'PARSE_FAILED' };
    }

    if (trimmedLength < 20) {
      return { ok: false, code: 'NEEDS_OCR' };
    }

    if (
      typeof pageCount === 'number' &&
      Number.isFinite(pageCount) &&
      pageCount > 0 &&
      extractedTextLength < pageCount * 20
    ) {
      return { ok: false, code: 'NEEDS_OCR' };
    }

    if (pageCount === null && extractedTextLength === 0) {
      return { ok: false, code: 'NEEDS_OCR' };
    }

    return { ok: true };
  } catch {
    return { ok: false, code: 'PARSE_FAILED' };
  }
}

