function detectPII(text) {
  if (typeof text !== 'string' || text.length === 0) {
    return { pii_types: [] };
  }

  const pii_types = [];
  for (const detector of DETECTORS) {
    if (detector.pattern.test(text)) {
      pii_types.push(detector.type);
    }
  }

  return { pii_types };
}

