"use strict";

const REQUIRED_KEYS = [
  'decision',
  'risk_level',
  'pii_types',
  'source_quality',
  'title',
  'carrier',
  'product_line',
  'state_codes',
  'topic',
  'valid_from',
  'valid_to',
  'caveats',
  'reason_codes',
];

const ALLOWED_DECISIONS = new Set(['clear', 'hold']);
const ALLOWED_RISK_LEVELS = new Set(['low', 'medium', 'high']);
const ALLOWED_PII_TYPES = new Set([
  'ssn',
  'phone',
  'email',
  'address',
  'policy_or_member_id',
  'person_name_hint',
]);
const ALLOWED_REASON_CODES = new Set([
  'PII_SUSPECTED',
  'NEEDS_OCR',
  'ACTIVE_CONTENT',
  'PARSE_FAILED',
  'SOURCE_WEAK',
  'MODEL_JSON_INVALID',
]);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }

  return Object.prototype.toString.call(value) === '[object Object]';
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function isIsoDateOnly(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }

  const date = new Date(value + 'T00:00:00.000Z');
  return (
    Number.isFinite(date.getTime()) &&
    date.toISOString().slice(0, 10) === value
  );
}

function validateArrayOfStrings(obj, fieldName, errors, allowedValues = null) {
  const value = obj[fieldName];
  if (!Array.isArray(value)) {
    errors.push(fieldName + ' must be an array of strings');
    return;
  }

  value.forEach((entry, index) => {
    if (typeof entry !== 'string') {
      errors.push(fieldName + '[' + index + '] must be a string');
      return;
    }

    if (allowedValues && !allowedValues.has(entry)) {
      errors.push(fieldName + '[' + index + '] contains an invalid value');
    }
  });
}

function validateReview(obj) {
  try {
    const errors = [];

    if (!isPlainObject(obj)) {
      return {
        valid: false,
        errors: ['object must be a plain object'],
      };
    }

    const actualKeys = Object.keys(obj);
    const requiredKeySet = new Set(REQUIRED_KEYS);

    for (const key of REQUIRED_KEYS) {
      if (!hasOwn(obj, key)) {
        errors.push(key + ' is required');
      }
    }

    for (const key of actualKeys) {
      if (!requiredKeySet.has(key)) {
        errors.push(key + ' is not an allowed top-level field');
      }
    }

    if (hasOwn(obj, 'decision')) {
      if (typeof obj.decision !== 'string' || !ALLOWED_DECISIONS.has(obj.decision)) {
        errors.push('decision must be exactly "clear" or "hold"');
      }
    }

    if (hasOwn(obj, 'risk_level')) {
      if (
        typeof obj.risk_level !== 'string' ||
        !ALLOWED_RISK_LEVELS.has(obj.risk_level)
      ) {
        errors.push('risk_level must be exactly "low", "medium", or "high"');
      }
    }

    if (hasOwn(obj, 'pii_types')) {
      validateArrayOfStrings(obj, 'pii_types', errors, ALLOWED_PII_TYPES);
    }

    if (hasOwn(obj, 'source_quality')) {
      if (
        typeof obj.source_quality !== 'number' ||
        Number.isNaN(obj.source_quality) ||
        obj.source_quality < 0 ||
        obj.source_quality > 1
      ) {
        errors.push('source_quality must be a number from 0 through 1');
      }
    }

    if (hasOwn(obj, 'title')) {
      if (typeof obj.title !== 'string' || obj.title.length === 0) {
        errors.push('title must be a non-empty string');
      }
    }

    if (hasOwn(obj, 'carrier')) {
      if (typeof obj.carrier !== 'string' && obj.carrier !== null) {
        errors.push('carrier must be a string or null');
      }
    }

    if (hasOwn(obj, 'product_line')) {
      if (typeof obj.product_line !== 'string' && obj.product_line !== null) {
        errors.push('product_line must be a string or null');
      }
    }

    if (hasOwn(obj, 'state_codes')) {
      if (!Array.isArray(obj.state_codes)) {
        errors.push('state_codes must be an array of two-letter state codes');
      } else {
        obj.state_codes.forEach((entry, index) => {
          if (typeof entry !== 'string' || !/^[A-Z]{2}$/.test(entry)) {
            errors.push('state_codes[' + index + '] must match /^[A-Z]{2}$/');
          }
        });
      }
    }

    if (hasOwn(obj, 'topic')) {
      if (typeof obj.topic !== 'string' && obj.topic !== null) {
        errors.push('topic must be a string or null');
      }
    }

    if (hasOwn(obj, 'valid_from')) {
      if (obj.valid_from !== null && !isIsoDateOnly(obj.valid_from)) {
        errors.push('valid_from must be an ISO date string YYYY-MM-DD or null');
      }
    }

    if (hasOwn(obj, 'valid_to')) {
      if (obj.valid_to !== null && !isIsoDateOnly(obj.valid_to)) {
        errors.push('valid_to must be an ISO date string YYYY-MM-DD or null');
      }
    }

    if (
      hasOwn(obj, 'valid_from') &&
      hasOwn(obj, 'valid_to') &&
      isIsoDateOnly(obj.valid_from) &&
      isIsoDateOnly(obj.valid_to) &&
      obj.valid_to < obj.valid_from
    ) {
      errors.push('valid_to must not be earlier than valid_from');
    }

    if (hasOwn(obj, 'caveats')) {
      validateArrayOfStrings(obj, 'caveats', errors);
    }

    if (hasOwn(obj, 'reason_codes')) {
      validateArrayOfStrings(obj, 'reason_codes', errors, ALLOWED_REASON_CODES);
    }

    if (hasOwn(obj, 'decision') && hasOwn(obj, 'reason_codes')) {
      if (obj.decision === 'hold' && Array.isArray(obj.reason_codes) && obj.reason_codes.length === 0) {
        errors.push('reason_codes must contain at least one entry when decision is hold');
      }

      if (obj.decision === 'clear' && Array.isArray(obj.reason_codes) && obj.reason_codes.length > 0) {
        errors.push('reason_codes must be empty when decision is clear');
      }
    }

    if (errors.length > 0) {
      return {
        valid: false,
        errors,
      };
    }

    return { valid: true };
  } catch (error) {
    return {
      valid: false,
      errors: ['object could not be validated: ' + error.message],
    };
  }
}

