  return [h0,h1,h2,h3,h4,h5,h6,h7].map(x => x.toString(16).padStart(8, '0')).join('');
}
const CHUNK_SIZE = 800;
const OVERLAP = 100;
const inputItems = $input.all();
const approvedItems = $('Validate Index Preconditions').all();
const out = [];

function toUuid(md5Hex) {
  return md5Hex.slice(0, 8) + '-' + md5Hex.slice(8, 12) + '-' + md5Hex.slice(12, 16) + '-' + md5Hex.slice(16, 20) + '-' + md5Hex.slice(20, 32);
}

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const src = approvedItems[i] && approvedItems[i].json ? approvedItems[i].json : null;
  if (!src) {
    throw new Error('CHUNK_FAILED: missing approved source metadata for item ' + i);
  }

  const keys = Object.keys(item.binary || {});
  if (keys.length === 0) {
    throw new Error('CHUNK_FAILED: no binary property found for item ' + i);
  }

  const key = keys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const sourceSha256 = sha256Hex(buffer.toString('utf8')); 
  if (src.sha256 && sourceSha256 !== src.sha256) {
    throw new Error('SUPERSEDE_CONFLICT: source hash mismatch for document_version_id ' + src.document_version_id);
  }

  const text = buffer.toString('utf8');
  if (!text.trim()) {
    throw new Error('EMPTY_TEXT: document_version_id ' + src.document_version_id);
  }

  const chunks = [];
  let start = 0;
  while (start < text.length) {
    const end = Math.min(start + CHUNK_SIZE, text.length);
    const chunkText = text.slice(start, end).trim();
    if (chunkText.length > 0) {
      chunks.push({ start, end, chunkText });
    }
    if (end >= text.length) {
      break;
    }
    start = end - OVERLAP;
    if (start < 0) {
      start = 0;
    }
  }

  if (chunks.length === 0) {
    throw new Error('EMPTY_TEXT: document_version_id ' + src.document_version_id);
  }

  for (let chunkIndex = 0; chunkIndex < chunks.length; chunkIndex++) {
    const chunk = chunks[chunkIndex];
    const chunkDigest = sha256Hex(src.document_version_id + ':' + chunkIndex);
    const chunkId = toUuid(chunkDigest);
    out.push({
      json: {
        document_version_id: src.document_version_id,
        file_name: src.file_name,
        raw_path: src.raw_path,
        sha256: src.sha256,
        source_sha256: sourceSha256,
        allow_supersede_replace: src.allow_supersede_replace,
        superseded_version_ids: src.superseded_version_ids,
        chunk_id: chunkId,
        chunk_index: chunkIndex,
        chunk_text: chunk.chunkText,
        token_count: Math.ceil(chunk.chunkText.length / 4),
        cite_locator: 'chars ' + chunk.start + '-' + chunk.end,
        expected_chunk_count: chunks.length,
        vertex_project_id_confirmed: src.vertex_project_id_confirmed,
        vertex_embedding_model_confirmed: src.vertex_embedding_model_confirmed,
        vertex_embedding_output_dimension_confirmed: src.vertex_embedding_output_dimension_confirmed
      }
    });
  }
}

return out;

const items = $input.all();
if (items.length === 0) {
  throw new Error('COUNT_MISMATCH: no chunk items received');
}

const groups = new Map();
for (const item of items) {
  const docId = item.json.document_version_id;
  if (!groups.has(docId)) {
    groups.set(docId, []);
  }
  groups.get(docId).push(item);
}

const out = [];
for (const [docId, groupItems] of groups.entries()) {
  const expected = Number(groupItems[0].json.expected_chunk_count || groupItems.length);
  const existingCounts = [...new Set(groupItems.map((item) => Number(item.json.existing_chunk_count || 0)))];
  if (existingCounts.length !== 1) {
    throw new Error('COUNT_MISMATCH: inconsistent existing chunk counts for document_version_id ' + docId);
  }

  const existing = existingCounts[0];
  const src = groupItems[0].json;
  if (existing === expected) {
    out.push({
      json: {
        index_status: 'already_indexed',
        ok: true,
        code: 'INDEX_COMPLETE',
        document_version_id: docId,
        chunk_count: expected,
        embedding_count: expected,
        superseded_version_ids: src.superseded_version_ids || [],
        source_sha256: src.source_sha256,
        allow_supersede_replace: src.allow_supersede_replace === true,
        dedupe_mode: 'chunk_id_conflict_prevented_duplicate_rows'
      }
    });
    continue;
  }

  if (existing > 0 && existing < expected) {
    throw new Error('COUNT_MISMATCH: partial existing chunk set for document_version_id ' + docId + ' existing=' + existing + ' expected=' + expected);
  }

  for (const item of groupItems) {
    out.push({
      json: {
        ...item.json,
        index_status: 'fresh'
      }
    });
  }
}

return out;

