const emb = await this.getInputConnectionData('ai_embedding', 0);
const items = $input.all();
const out = [];
for (const item of items) {
  const text = item.json.chunk_text;
  let vector = null;
  let callError = null;
  try {
    vector = await emb.embedQuery(text);
  } catch (e) {
    callError = e && e.message ? e.message : String(e);
  }
  out.push({
    json: {
      ...item.json,
      embedding_raw: Array.isArray(vector) ? vector : null,
      embedding_call_error: callError
    }
  });
}
return out;

