const chunkJson = $json || {};
const documentVersionId = chunkJson.document_version_id;
const chunkIndex = chunkJson.chunk_index;

if (chunkJson.embedding_call_error) {
  throw new Error('EMBED_FAILED: embedding call error for document_version_id ' + documentVersionId + ' chunk_index ' + chunkIndex + ': ' + chunkJson.embedding_call_error);
}

const embedding = chunkJson.embedding_raw;
if (!Array.isArray(embedding) || embedding.length === 0) {
  throw new Error('EMBED_FAILED: no embedding vector returned for document_version_id ' + documentVersionId + ' chunk_index ' + chunkIndex);
}

const expectedDimensionsRaw = chunkJson.vertex_embedding_output_dimension_confirmed;
const expectedDimensions = Number(expectedDimensionsRaw);
if (Number.isFinite(expectedDimensions) && expectedDimensions > 0 && embedding.length !== expectedDimensions) {
  throw new Error('DIMENSION_MISMATCH: expected ' + expectedDimensions + ' actual ' + embedding.length + ' for document_version_id ' + documentVersionId + ' chunk_index ' + chunkIndex);
}

return {
  json: {
    ...chunkJson,
    ok: true,
    fault_code: null,
    embedding_vector: JSON.stringify(embedding),
    embedding_dimensions_actual: embedding.length,
    embedding_dimensions_expected: expectedDimensionsRaw,
    embedding_model: chunkJson.vertex_embedding_model_confirmed
  }
};

const insertedItems = $input.all();
if (insertedItems.length === 0) {
  throw new Error('COUNT_MISMATCH: no inserted chunk rows returned');
}

const chunkItems = $('Chunk Text').all();
const embeddedItems = $('Handle Embed Result').all();
const groups = new Map();
for (const item of insertedItems) {
  const docId = item.json.document_version_id;
  if (!groups.has(docId)) {
    groups.set(docId, []);
  }
  groups.get(docId).push(item);
}

const out = [];
for (const [docId, insertedGroup] of groups.entries()) {
  const chunkGroup = chunkItems.filter((item) => item.json.document_version_id === docId);
  const embedGroup = embeddedItems.filter((item) => item.json.document_version_id === docId);
  if (chunkGroup.length === 0) {
    throw new Error('COUNT_MISMATCH: missing chunk metadata for document_version_id ' + docId);
  }

  const expected = Number(chunkGroup[0].json.expected_chunk_count || chunkGroup.length);
  if (chunkGroup.length !== expected) {
    throw new Error('COUNT_MISMATCH: chunk count metadata mismatch for document_version_id ' + docId + ' expected=' + expected + ' actual=' + chunkGroup.length);
  }
  if (embedGroup.length !== expected) {
    throw new Error('EMBED_FAILED: embedding count mismatch for document_version_id ' + docId + ' expected=' + expected + ' actual=' + embedGroup.length);
  }
  if (insertedGroup.length !== expected) {
    throw new Error('COUNT_MISMATCH: inserted=' + insertedGroup.length + ' expected=' + expected + ' for document_version_id ' + docId);
  }
  if (embedGroup.some((item) => !item.json || typeof item.json.embedding_vector !== 'string' || item.json.embedding_vector.length === 0)) {
    throw new Error('EMBED_FAILED: a chunk without a valid embedding reached the finalize step for document_version_id ' + docId);
  }

  out.push({
    json: {
      ok: true,
      code: 'INDEX_COMPLETE',
      document_version_id: docId,
      chunk_count: expected,
      embedding_count: embedGroup.length,
      superseded_version_ids: chunkGroup[0].json.superseded_version_ids || [],
      source_sha256: chunkGroup[0].json.source_sha256,
      allow_supersede_replace: chunkGroup[0].json.allow_supersede_replace === true,
      dedupe_mode: 'deterministic_chunk_id'
    }
  });
}

return out;

const chunk = $('Chunk Text').item.json;
const existing = Number($json.existing_chunk_count);
if (!Number.isInteger(existing) || existing < 0) throw new Error('COUNT_MISMATCH: invalid existing chunk count');
return { json: { ...chunk, existing_chunk_count: existing } };
